# Publikacje MVP: typ, obszar, tytuł roboczy H1, fraza główna, frazy poboczne (long tail), intencja, segment, URL, format pozycji zerowej,
# ocena jakościowa: popyt, wartość, szansa, pilność (1–3), sezonowość, fala (1: do 20.11, 2: do 4.12, start: tydzień startu)
P = []
def pub(typ, obszar, h1, fraza, poboczne, intencja, segment, url, format_pz, popyt, wartosc, szansa, pilnosc, sezon, fala):
    P.append(dict(typ=typ, obszar=obszar, h1=h1, fraza=fraza, poboczne=poboczne, intencja=intencja, segment=segment, url=url,
                  format_pz=format_pz, popyt=popyt, wartosc=wartosc, szansa=szansa, pilnosc=pilnosc, sezon=sezon, fala=fala))

